window.registerChapter({"num": 104, "source_label": "Appendix A", "title": "Therapeutic Agents", "group": "Reference appendices", "features": ["Prematurity", "Apnea", "Cardiac shunting", "Shock / perfusion", "Arrhythmia", "Infection / inflammation", "Jaundice / cholestasis", "Anemia / polycythemia", "Bleeding / thrombosis", "Seizures", "Feeding difficulty", "Abdominal distension", "Intestinal injury", "Glucose disturbance", "Electrolyte / acid–base", "Endocrine disorder", "Skin findings", "Eye / hearing"], "pdf_start": 2099, "pdf_end": 2107, "printed_start": "2109", "printed_end": "2117", "figures": [], "tables": [], "cards": 6, "summary": "Postmenstrual and postnatal age. The footnote specifies dependence on postmenstrual and postnatal age; a printed range is not a complete individualized prescription.", "pillars": [{"label": "Developmental dosing", "text": "Postmenstrual and postnatal age. The footnote specifies dependence on postmenstrual and postnatal age; a printed range is not a complete individualized prescription.", "pdf_page": 2107, "printed_page": "2117"}, {"label": "Compatibility and bilirubin", "text": "Avoid its use in hyperbilirubinemia and do not administer in the same IV line with calcium-containing solutions. The source row includes both bilirubin and same-line calcium cautions; these are essential parts of reading the entry.", "pdf_page": 2099, "printed_page": "2109"}, {"label": "Equivalent units", "text": "Phenytoin-equivalent amount rather than an unspecified mass of product. The table defines PE as phenytoin equivalent and relates one mg PE to one mg phenytoin; product units must remain explicit.", "pdf_page": 2104, "printed_page": "2114"}, {"label": "Paralysis and comfort", "text": "Blockade provides neither analgesia nor amnesia, so effective sedation/analgesia must accompany it. The footnote states that these agents provide neither analgesia nor amnesia, so visible immobility cannot establish comfort.", "pdf_page": 2107, "printed_page": "2117"}, {"label": "Anticoagulant monitoring", "text": "Anti-factor Xa activity. The enoxaparin row specifies anti-factor Xa-guided adjustment; bleeding assessment and other monitoring remain clinically relevant.", "pdf_page": 2106, "printed_page": "2116"}], "reader_html": "<section class=\"source-section\" data-pdf-page=\"2099\"><h2>PDF page 2099 · Printed 2109</h2><h3>Overview</h3><p>Appendix A</p><small class=\"source\">PDF p. 2099</small><p>Jacquelyn D. McClary Therapeutic Agents</p><small class=\"source\">PDF p. 2099</small><p>Agent Dosage</p><small class=\"source\">PDF p. 2099</small><p>Anti-Infective Agents Antibacterials</p><small class=\"source\">PDF p. 2099</small><p>Amikacina 12–14 mg/kg/dose every 24–48 h</p><small class=\"source\">PDF p. 2099</small><p>Ampicillina Meningitis: 100 mg/kg/dose IV every 6–12 h Non-CNS infections: 25–50 mg/kg/dose IV, IM every 6–12 h</p><small class=\"source\">PDF p. 2099</small><p>Azithromycin Pertussis/ureaplasma infections: 10 mg/kg/dose PO, IV</p><small class=\"source\">PDF p. 2099</small><p>every 24 h Chlamydial conjunctivitis: 20 mg/kg PO, IV every 24 h ×</p><small class=\"source\">PDF p. 2099</small><p>3 d</p><small class=\"source\">PDF p. 2099</small><p>Aztreonama 30 mg/kg/dose IV, IM every 6–12 h</p><small class=\"source\">PDF p. 2099</small><p>Cefazolina 25 mg/kg/dose IV, IM every 6–12 h</p><small class=\"source\">PDF p. 2099</small><p>Cefepimea 50 mg/kg/dose IV, IM every 12 h</p><small class=\"source\">PDF p. 2099</small><p>Cefotaximea Sepsis or meningitis: 50 mg/kg/dose IV, IM every 6–12 h Disseminated gonococcal infection: 25 mg/kg/dose IV, IM</p><small class=\"source\">PDF p. 2099</small><p>every 12 h for 7 d if meningitis not present</p><small class=\"source\">PDF p. 2099</small><p>Cefoxitin 30 mg/kg/dose IV, IM every 8 h</p><small class=\"source\">PDF p. 2099</small><p>Ceftazidimea 50 mg/kg/dose IV, IM every 8–12 h</p><small class=\"source\">PDF p. 2099</small><p>Ceftriaxone Sepsis: 50 mg/kg/dose IV, IM every 24 h Meningitis: 100 mg/kg/dose IV, IM every 24 h Disseminated gonococcal infection: 25–50 mg/kg/dose</p><small class=\"source\">PDF p. 2099</small><p>IV, IM every 24 h Gonococcal infection prophylaxis/ophthalmia: 25–50 mg/</p><small class=\"source\">PDF p. 2099</small><p>kg (max 125 mg) IV, IM single dose</p><small class=\"source\">PDF p. 2099</small><p>Clindamycina 5–7.5 mg/kg/dose IV, PO every 6–12 h</p><small class=\"source\">PDF p. 2099</small><p>Erythromycin 10–12.5 mg/kg/dose PO every 6 h Severe infection: 5–10 mg/kg IV every 6 h</p><small class=\"source\">PDF p. 2099</small><p>Comments</p><small class=\"source\">PDF p. 2099</small><p>Monitor serum concentrations if treating</p><small class=\"source\">PDF p. 2099</small><p>&gt;48 h.</p><small class=\"source\">PDF p. 2099</small><p>—</p><small class=\"source\">PDF p. 2099</small><p>IV dosing is not well defined in neonates.</p><small class=\"source\">PDF p. 2099</small><p>—</p><small class=\"source\">PDF p. 2099</small><p>First-generation cephalosporin is</p><small class=\"source\">PDF p. 2099</small><p>commonly used for perioperative prophylaxis and treatment of urinary tract and soft tissue infections.</p><small class=\"source\">PDF p. 2099</small><p>Fourth-generation cephalosporin is</p><small class=\"source\">PDF p. 2099</small><p>reserved for treatment of infections caused by multidrug-resistant organisms.</p><small class=\"source\">PDF p. 2099</small><p>Broad-spectrum, third-generation</p><small class=\"source\">PDF p. 2099</small><p>cephalosporin may be used to treat gram-negative meningitis.</p><small class=\"source\">PDF p. 2099</small><p>Use is limited to skin, intra-abdominal, and</p><small class=\"source\">PDF p. 2099</small><p>urinary tract infections.</p><small class=\"source\">PDF p. 2099</small><p>Third-generation cephalosporin is effective</p><small class=\"source\">PDF p. 2099</small><p>against Pseudomonas species.</p><small class=\"source\">PDF p. 2099</small><p>Not recommended for infants with</p><small class=\"source\">PDF p. 2099</small><p>hyperbilirubinemia; do not administer in the same IV line with calcium-containing solutions.</p><small class=\"source\">PDF p. 2099</small><p>Do not use to treat meningitis, as it may</p><small class=\"source\">PDF p. 2099</small><p>cause pseudomembranous colitis.</p><small class=\"source\">PDF p. 2099</small><p>Higher doses are used to treat chlamydial</p><small class=\"source\">PDF p. 2099</small><p>pneumonitis and conjunctivitis and pertussis.</p><small class=\"source\">PDF p. 2099</small><p>2109</p><small class=\"source\">PDF p. 2099</small><figure class=\"source-page\"><a href=\"tables/ch104_page2099.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch104_page2099.jpg\" alt=\"Original source page 2099, including its figures or tables\"></a><figcaption>Original source-page view · PDF 2099. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"2100\"><h2>PDF page 2100 · Printed 2110</h2><h3>Overview</h3><p>Agent Dosage</p><small class=\"source\">PDF p. 2100</small><p>Gentamicina 4–5 mg/kg/dose IV, IM every 24–48 h</p><small class=\"source\">PDF p. 2100</small><p>Imipenem/cilastatin 20–25 mg/kg/dose (imipenem component) IV every 8–12 h</p><small class=\"source\">PDF p. 2100</small><p>Linezolid 10 mg/kg/dose IV, PO every 8 h (premature infants &lt;7 d of</p><small class=\"source\">PDF p. 2100</small><p>age: dose every 12 h)</p><small class=\"source\">PDF p. 2100</small><p>Meropenema 20–40 mg/kg/dose IV every 8–12 h</p><small class=\"source\">PDF p. 2100</small><p>Metronidazolea Loading dose: 15 mg/kg/dose IV, PO Maintenance dose: 7.5–10 mg/kg/dose IV, PO every 6–24 h</p><small class=\"source\">PDF p. 2100</small><p>Nafcillina Sepsis: 25 mg/kg/dose IV every 6–12 h Meningitis: 50 mg/kg/dose IV every 6–12 h</p><small class=\"source\">PDF p. 2100</small><p>Oxacillina Sepsis: 25 mg/kg/dose IV every 6–12 h Meningitis: 50 mg/kg/dose IV every 6–12 h</p><small class=\"source\">PDF p. 2100</small><p>Penicillin Ga Sepsis: 25,000–50,000 units/kg/dose IV, IM every 6–12 h Meningitis: 75,000–150,000 units/kg/dose IV, IM every</p><small class=\"source\">PDF p. 2100</small><p>6–12 h</p><small class=\"source\">PDF p. 2100</small><p>Piperacillin/</p><small class=\"source\">PDF p. 2100</small><p>100 mg/kg/dose (as piperacillin component) IV every 8–12 h</p><small class=\"source\">PDF p. 2100</small><p>tazobactama</p><small class=\"source\">PDF p. 2100</small><p>Rifampin PO: 10–20 mg/kg/dose every 24 h IV: 5–10 mg/kg/dose every 12 h Prophylaxis against meningococcal disease: 5 mg/kg/</p><small class=\"source\">PDF p. 2100</small><p>dose PO every 12 h for 2 d Prophylaxis against Haemophilus influenzae type B</p><small class=\"source\">PDF p. 2100</small><p>disease: 10 mg/kg/dose PO every 24 h for 4 d</p><small class=\"source\">PDF p. 2100</small><p>Tobramycina 4–5 mg/kg/dose every 24–48 h</p><small class=\"source\">PDF p. 2100</small><p>Vancomycina 10–15 mg/kg/dose every 6–18 h</p><small class=\"source\">PDF p. 2100</small><p>Antifungals</p><small class=\"source\">PDF p. 2100</small><p>Amphotericin B 1 mg/kg/dose IV every 24 h</p><small class=\"source\">PDF p. 2100</small><p>Amphotericin</p><small class=\"source\">PDF p. 2100</small><p>2.5–7 mg/kg/dose IV every 24 h</p><small class=\"source\">PDF p. 2100</small><p>B liposome (Ambisome)</p><small class=\"source\">PDF p. 2100</small><p>Amphotericin B lipid</p><small class=\"source\">PDF p. 2100</small><p>2.5–5 mg/kg/dose IV every 24 h</p><small class=\"source\">PDF p. 2100</small><p>complex (Abelecet)</p><small class=\"source\">PDF p. 2100</small><p>Caspofungin 25 mg/m2/dose IV every 24 h</p><small class=\"source\">PDF p. 2100</small><p>Comments</p><small class=\"source\">PDF p. 2100</small><p>Monitor serum concentrations if treating</p><small class=\"source\">PDF p. 2100</small><p>&gt;48 h.</p><small class=\"source\">PDF p. 2100</small><p>Restrict use to treatment of non-CNS</p><small class=\"source\">PDF p. 2100</small><p>infections; seizures occur frequently in patients with meningitis.</p><small class=\"source\">PDF p. 2100</small><p>Use for gram-positive infections refractory</p><small class=\"source\">PDF p. 2100</small><p>to conventional therapy.</p><small class=\"source\">PDF p. 2100</small><p>Reserve for infections caused by</p><small class=\"source\">PDF p. 2100</small><p>multidrug-resistant organisms; restrict use of 40 mg/kg doses to full-term infants with meningitis.</p><small class=\"source\">PDF p. 2100</small><p>—</p><small class=\"source\">PDF p. 2100</small><p>Greatest CSF penetration of</p><small class=\"source\">PDF p. 2100</small><p>antistaphylococcal penicillins; predominantly biliary excretion; irritating to veins.</p><small class=\"source\">PDF p. 2100</small><p>Poor CSF penetration, so choose an</p><small class=\"source\">PDF p. 2100</small><p>alternative agent for meningitis when possible; irritating to veins.</p><small class=\"source\">PDF p. 2100</small><p>Doses at the high end of the dosing range</p><small class=\"source\">PDF p. 2100</small><p>and IV route are suggested for severe group B streptococcal infections.</p><small class=\"source\">PDF p. 2100</small><p>For non-CNS infections caused by</p><small class=\"source\">PDF p. 2100</small><p>susceptible β-lactamase–producing bacteria.</p><small class=\"source\">PDF p. 2100</small><p>Used in combination with vancomycin</p><small class=\"source\">PDF p. 2100</small><p>or aminoglycosides for treatment of persistent staphylococcal infections.</p><small class=\"source\">PDF p. 2100</small><p>Monitor serum concentrations if treating</p><small class=\"source\">PDF p. 2100</small><p>&gt;48 h.</p><small class=\"source\">PDF p. 2100</small><p>Target trough concentrations are</p><small class=\"source\">PDF p. 2100</small><p>10–15 μg/mL for most infections; 15–20 μg/mL may be necessary for meningitis, pneumonia, and other severe infections. AUC:MIC ratio may be used to adjust</p><small class=\"source\">PDF p. 2100</small><p>dose when available.</p><small class=\"source\">PDF p. 2100</small><p>Infuse over 2–6 h; monitor serum</p><small class=\"source\">PDF p. 2100</small><p>creatinine and prolong dosing interval if creatinine increases &gt;0.4 mg/dL from baseline.</p><small class=\"source\">PDF p. 2100</small><p>Infuse over 2 h; less nephrotoxic than</p><small class=\"source\">PDF p. 2100</small><p>amphotericin B.</p><small class=\"source\">PDF p. 2100</small><p>Infuse over 2 h; less nephrotoxic than</p><small class=\"source\">PDF p. 2100</small><p>amphotericin B.</p><small class=\"source\">PDF p. 2100</small><p>Limited data in neonates, so reserve for</p><small class=\"source\">PDF p. 2100</small><p>treatment of refractory candidemia or patients intolerant to amphotericin.</p><small class=\"source\">PDF p. 2100</small><figure class=\"source-page\"><a href=\"tables/ch104_page2100.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch104_page2100.jpg\" alt=\"Original source page 2100, including its figures or tables\"></a><figcaption>Original source-page view · PDF 2100. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"2101\"><h2>PDF page 2101 · Printed 2111</h2><h3>Overview</h3><p>Agent Dosage</p><small class=\"source\">PDF p. 2101</small><p>Fluconazolea Systemic infection: loading dose 12–25 mg/kg/dose IV,</p><small class=\"source\">PDF p. 2101</small><p>PO, then 6–12 mg/kg/dose every 24–48 h Prophylaxis: 3–6 mg/kg/dose IV, PO 2×/wk Thrush: 6 mg/kg/dose PO on day 1, then 3 mg/kg/dose</p><small class=\"source\">PDF p. 2101</small><p>PO every 24 h</p><small class=\"source\">PDF p. 2101</small><p>Flucytosine 12.5–37.5 mg/kg/dose PO every 6 h</p><small class=\"source\">PDF p. 2101</small><p>Micafungin 4–10 mg/kg/dose IV every 24 h</p><small class=\"source\">PDF p. 2101</small><p>Nystatin Topical: apply to affected area every 6 h Thrush: 1 mL (premature) to 2 mL (full term) of 100,000</p><small class=\"source\">PDF p. 2101</small><p>unit/mL suspension; swab inside mouth every 6 h</p><small class=\"source\">PDF p. 2101</small><p>Antivirals</p><small class=\"source\">PDF p. 2101</small><p>Acyclovira HSV treatment: 20 mg/kg/dose IV every 6–12 h HSV chronic suppression: 300 mg/m2/dose PO every 8 h Varicella-zoster virus: 10–15 mg/kg/dose IV every 8 h</p><small class=\"source\">PDF p. 2101</small><p>Ganciclovir Treatment: 6 mg/kg/dose IV every 12 h Chronic suppression: 30–40 mg/kg/dose PO every 8 h</p><small class=\"source\">PDF p. 2101</small><p>Lamivudine 2 mg/kg/dose PO every 12 h</p><small class=\"source\">PDF p. 2101</small><p>Nevirapinea 2–6 mg/kg/dose PO every 12 h</p><small class=\"source\">PDF p. 2101</small><p>Oseltamivira 1–3 mg/kg/dose PO every 12 h for 5 d</p><small class=\"source\">PDF p. 2101</small><p>Valganciclovir 16 mg/kg/dose PO every 12 h</p><small class=\"source\">PDF p. 2101</small><p>Zidovudinea IV: 1.5–3 mg/kg/dose every 12 h PO: 2–4 mg/kg/dose every 12 h</p><small class=\"source\">PDF p. 2101</small><p>Cardiovascular Drugs Antiarrhythmics</p><small class=\"source\">PDF p. 2101</small><p>Adenosine Give 50 μg/kg as a rapid IV bolus followed by a flush;</p><small class=\"source\">PDF p. 2101</small><p>increase dose in 50 μg/kg increments every 2 min until response is obtained (maximum dose of 300 μg/kg/ dose)</p><small class=\"source\">PDF p. 2101</small><p>Comments</p><small class=\"source\">PDF p. 2101</small><p>Higher doses are used for severe</p><small class=\"source\">PDF p. 2101</small><p>infections; for patients with renal dysfunction (CrCl &lt;50 mL/min), administer the normal loading dose and decrease the daily dose by 50%; may cause reversible elevations of transaminases and may interfere with metabolism of phenytoin, barbiturates, caffeine, and midazolam.</p><small class=\"source\">PDF p. 2101</small><p>Use in conjunction with amphotericin B or</p><small class=\"source\">PDF p. 2101</small><p>fluconazole; increase dosing interval in presence of renal dysfunction.</p><small class=\"source\">PDF p. 2101</small><p>Data in neonates are limited, so reserve for</p><small class=\"source\">PDF p. 2101</small><p>treatment of refractory candidemia or for patients intolerant to amphotericin.</p><small class=\"source\">PDF p. 2101</small><p>Continue for 3 d after symptoms subside.</p><small class=\"source\">PDF p. 2101</small><p>Administer every 12–24 h in patients</p><small class=\"source\">PDF p. 2101</small><p>with severe renal/hepatic impairment; neutropenia or phlebitis may occur.</p><small class=\"source\">PDF p. 2101</small><p>Significant neutropenia occurs in some</p><small class=\"source\">PDF p. 2101</small><p>patients; reduce dose by half for ANC &lt;500 cells/mm3.</p><small class=\"source\">PDF p. 2101</small><p>Refer to the Perinatal Guidelines at</p><small class=\"source\">PDF p. 2101</small><p>https://hivinfo.nih.gov/ for the latest treatment information and dosing recommendations beyond 4 weeks of life.</p><small class=\"source\">PDF p. 2101</small><p>Refer to the Perinatal Guidelines at</p><small class=\"source\">PDF p. 2101</small><p>https://hivinfo.nih.gov/ for the latest treatment information and dosing recommendations beyond 4 weeks of life.</p><small class=\"source\">PDF p. 2101</small><p>Limited data are available for preterm</p><small class=\"source\">PDF p. 2101</small><p>infants; may cause transient rise in transaminases.</p><small class=\"source\">PDF p. 2101</small><p>Neutropenia occurs frequently; dose</p><small class=\"source\">PDF p. 2101</small><p>adjustment is required for ANC &lt;500 cells/mm3.</p><small class=\"source\">PDF p. 2101</small><p>Initiate therapy within 6–12 h of birth.</p><small class=\"source\">PDF p. 2101</small><p>Anemia and neutropenia may occur. Refer to the Perinatal Guidelines at https://hivinfo.nih.gov/ for the latest treatment information and dosing recommendations beyond 4 weeks of life.</p><small class=\"source\">PDF p. 2101</small><p>May cause transient asystole or</p><small class=\"source\">PDF p. 2101</small><p>bradycardia prior to return of normal sinus rhythm.</p><small class=\"source\">PDF p. 2101</small><figure class=\"source-page\"><a href=\"tables/ch104_page2101.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch104_page2101.jpg\" alt=\"Original source page 2101, including its figures or tables\"></a><figcaption>Original source-page view · PDF 2101. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"2102\"><h2>PDF page 2102 · Printed 2112</h2><h3>Overview</h3><p>Agent Dosage</p><small class=\"source\">PDF p. 2102</small><p>Amiodarone Loading dose: 5 mg/kg IV over 20–60 min Continuous IV infusion: start at 7 μg/kg/min; may increase</p><small class=\"source\">PDF p. 2102</small><p>to 15 μg/kg/min PO: 5–10 mg/kg/dose every 12 h</p><small class=\"source\">PDF p. 2102</small><p>Atropine Bradycardia: 0.01–0.03 mg/kg/dose IV, IM, ET every</p><small class=\"source\">PDF p. 2102</small><p>10–15 min up to total dose of 0.04 mg/kg Premedication for intubation: 0.02 mg/kg/dose IV</p><small class=\"source\">PDF p. 2102</small><p>Digoxina &lt;37 weeks, loading dose: IV: 15–20 μg/kg divided into 3 doses over 24 h PO: 20–25 μg/kg divided into 3 doses over 24 h Maintenance dose: IV: 4–5 μg/kg every 24 h PO: 5–6 μg/kg every 24 h Loading dose, ≥37 weeks: IV: 30–40 μg/kg divided into 3 doses over 24 h PO: 40–50 μg/kg divided into 3 doses over 24 h Maintenance dose: IV: 4–5 μg/kg every 12 h PO: 5–6 μg/kg every 12 h</p><small class=\"source\">PDF p. 2102</small><p>Digoxin immune Fab Chronic digoxin toxicity: Dose (mg) = 40 mg × (serum digoxin concentration in ng/</p><small class=\"source\">PDF p. 2102</small><p>mL × weight in kg)/100 Acute ingestion: Dose (in vials) = (digoxin ingested in mg ×</p><small class=\"source\">PDF p. 2102</small><p>bioavailability)/0.5 mg</p><small class=\"source\">PDF p. 2102</small><p>Flecainide Begin at 2 mg/kg/dose PO every 12 h; adjust based on</p><small class=\"source\">PDF p. 2102</small><p>response and serum concentrations to a maximum of 4 mg/kg/dose PO every 12 h</p><small class=\"source\">PDF p. 2102</small><p>Lidocaine Initial bolus: 0.5–1 mg/kg dose by slow IV push; may be</p><small class=\"source\">PDF p. 2102</small><p>repeated every 10 min up to total of 5 mg/kg Maintenance IV infusion: 10–50 μg/kg/min</p><small class=\"source\">PDF p. 2102</small><p>Procainamide Initial bolus: 7–10 mg/kg/dose IV push Maintenance IV infusion: 20–80 μg/kg/min</p><small class=\"source\">PDF p. 2102</small><p>Propranolol PO: starting dose 0.25–1 mg/kg/dose every 6 h; increase</p><small class=\"source\">PDF p. 2102</small><p>up to 3.5 mg/kg/dose every 6 h IV: 0.01 mg/kg/dose IV every 6 h; increase up to 0.15 mg/</p><small class=\"source\">PDF p. 2102</small><p>kg/dose every 6 h</p><small class=\"source\">PDF p. 2102</small><p>Sotalol 1 mg/kg/dose PO every 12 h; increase every 3–5 d to a</p><small class=\"source\">PDF p. 2102</small><p>maximum of 4 mg/kg/dose PO every 12 h</p><small class=\"source\">PDF p. 2102</small><p>Antihypertensive Agents</p><small class=\"source\">PDF p. 2102</small><p>Captopril Begin at 0.01–0.05 mg/kg/dose PO every 8–12 h;</p><small class=\"source\">PDF p. 2102</small><p>increase to 0.1–1.6 mg/kg/d divided every 6–24 h</p><small class=\"source\">PDF p. 2102</small><p>PO: 40 μg/kg PO every 24 h; increase up to 150 μg/kg PO</p><small class=\"source\">PDF p. 2102</small><p>Enalapril (PO) Enalaprilat (IV)</p><small class=\"source\">PDF p. 2102</small><p>every 6 h IV: 10 μg/kg IV every 24 h; increase dose and interval</p><small class=\"source\">PDF p. 2102</small><p>based on response</p><small class=\"source\">PDF p. 2102</small><p>Hydralazine IV: 0.1–0.5 mg/kg/dose every 6–8 h; gradually increase to</p><small class=\"source\">PDF p. 2102</small><p>a maximum of 2 mg/kg/dose every 6 h PO: 0.25–1 mg/kg/dose every 6–8 h</p><small class=\"source\">PDF p. 2102</small><p>Comments</p><small class=\"source\">PDF p. 2102</small><p>For treatment of refractory supraventricular</p><small class=\"source\">PDF p. 2102</small><p>arrhythmia; has long elimination halflife; may cause hypothyroidism or hyperthyroidism, hepatitis, or pulmonary fibrosis.</p><small class=\"source\">PDF p. 2102</small><p>For reversal or prevention of sinus</p><small class=\"source\">PDF p. 2102</small><p>bradycardia.</p><small class=\"source\">PDF p. 2102</small><p>Loading dose is generally reserved for</p><small class=\"source\">PDF p. 2102</small><p>treatment of arrhythmias. Be aware of drug interactions, and obtain periodic ECGs to assess for desired effects and signs of toxicity. Hypokalemia, hypomagnesemia, hypermagnesemia, hypercalcemia, and renal impairment predispose patients to digoxin toxicity. Target trough concentration of 0.8–2 ng/ mL.</p><small class=\"source\">PDF p. 2102</small><p>Each vial contains 40 mg and will bind</p><small class=\"source\">PDF p. 2102</small><p>0.5 mg digoxin; after administration, digoxin serum concentrations can no longer be determined accurately. Bioavailability of the digoxin solution = 0.85, tablets = 0.8.</p><small class=\"source\">PDF p. 2102</small><p>Used for treatment of SVT not responsive</p><small class=\"source\">PDF p. 2102</small><p>to conventional therapies; correct serum potassium abnormalities prior to initiation. Steady-state plasma levels take 3–5 d to achieve.</p><small class=\"source\">PDF p. 2102</small><p>Most often used to treat ventricular</p><small class=\"source\">PDF p. 2102</small><p>arrhythmias; adverse effects include hypotension, seizures, respiratory depression, and asystole.</p><small class=\"source\">PDF p. 2102</small><p>Treatment of SVT refractory to vagal</p><small class=\"source\">PDF p. 2102</small><p>maneuvers and adenosine.</p><small class=\"source\">PDF p. 2102</small><p>Use extreme caution with IV dosing;</p><small class=\"source\">PDF p. 2102</small><p>adverse effects related to β-receptor blockade include bradycardia, bronchospasm, and hypoglycemia.</p><small class=\"source\">PDF p. 2102</small><p>For treatment of refractory ventricular and</p><small class=\"source\">PDF p. 2102</small><p>supraventricular tachyarrhythmias; has β-blocking properties and prolongs cardiac action potential duration.</p><small class=\"source\">PDF p. 2102</small><p>Treatment of hypertension and CHF;</p><small class=\"source\">PDF p. 2102</small><p>monitor renal function and serum potassium; contraindicated in patients with bilateral renovascular disease.</p><small class=\"source\">PDF p. 2102</small><p>Treatment of hypertension and CHF;</p><small class=\"source\">PDF p. 2102</small><p>monitor renal function and serum potassium; contraindicated in patients with bilateral renovascular disease.</p><small class=\"source\">PDF p. 2102</small><p>Treatment of hypertension via vasodilation;</p><small class=\"source\">PDF p. 2102</small><p>the oral dose is approximately twice the required IV dose.</p><small class=\"source\">PDF p. 2102</small><figure class=\"source-page\"><a href=\"tables/ch104_page2102.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch104_page2102.jpg\" alt=\"Original source page 2102, including its figures or tables\"></a><figcaption>Original source-page view · PDF 2102. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"2103\"><h2>PDF page 2103 · Printed 2113</h2><h3>Overview</h3><p>Agent Dosage</p><small class=\"source\">PDF p. 2103</small><p>Sodium nitroprusside 0.3 μg/kg/min continuous IV infusion; increase dose every</p><small class=\"source\">PDF p. 2103</small><p>few minutes as needed Maintenance dose is usually &lt;2 μg/kg/min For hypertensive crisis, can use doses as high as 10 μg/</p><small class=\"source\">PDF p. 2103</small><p>kg/min for ≤10 min</p><small class=\"source\">PDF p. 2103</small><p>Hemodynamic Support Agents</p><small class=\"source\">PDF p. 2103</small><p>Dobutamine 2–25 μg/kg/min continuous IV infusion</p><small class=\"source\">PDF p. 2103</small><p>Dopamine 2–20 μg/kg/min continuous IV infusion</p><small class=\"source\">PDF p. 2103</small><p>Epinephrine Resuscitation: 0.01–0.03 mg/kg/dose IV push; 0.05–</p><small class=\"source\">PDF p. 2103</small><p>0.1 mg/kg/dose ET Continuous IV infusion: 0.03–0.2 μg/kg/min typically; max</p><small class=\"source\">PDF p. 2103</small><p>dose 1 μg/kg/min</p><small class=\"source\">PDF p. 2103</small><p>Isoproterenol 0.05–0.5 μg/kg/min continuous IV infusion; titrate to</p><small class=\"source\">PDF p. 2103</small><p>maximum of 2 μg/kg/min</p><small class=\"source\">PDF p. 2103</small><p>Milrinone Loading dose: 50–75 μg/kg IV over 15–60 min Maintenance infusion: 0.3–0.75 μg/kg/min</p><small class=\"source\">PDF p. 2103</small><p>Patent Ductus Arteriosus Agents</p><small class=\"source\">PDF p. 2103</small><p>Acetaminophen IV/PO: 15 mg/kg every 6 h × 12 doses</p><small class=\"source\">PDF p. 2103</small><p>Alprostadil Initial dose: 0.05–0.1 μg/kg/min continuous IV infusion Maintenance doses may be as low as 0.01 μg/kg/min</p><small class=\"source\">PDF p. 2103</small><p>Ibuprofen lysine First dose: 10 mg/kg IV Second and third doses: 5 mg/kg IV; administer at 24 h</p><small class=\"source\">PDF p. 2103</small><p>intervals</p><small class=\"source\">PDF p. 2103</small><p>Indomethacin Initial dose: 0.2 mg/kg IV Subsequent doses: If &lt;2 d, 0.1 mg/kg/dose IV every 12–24 h for 2 doses If 2–7 d, 0.2 mg/kg/dose IV every 12–24 h for 2 doses If &gt;7 d, 0.25 mg/kg dose IV every 12–24 h for 2 doses</p><small class=\"source\">PDF p. 2103</small><p>Central Nervous System Drugs Analgesics and Narcotics</p><small class=\"source\">PDF p. 2103</small><p>Acetaminophena PO/rectal: 10–15 mg/kg/dose every 6–12 h IV: GA ≥32 weeks, 12.5 mg/kg every 6 h</p><small class=\"source\">PDF p. 2103</small><p>Fentanyl Slow IV push: 1–4 μg/kg/dose every 2–4 h Continuous IV infusion: 0.5–2 μg/kg/h typically; max dose</p><small class=\"source\">PDF p. 2103</small><p>5 μg/kg/h</p><small class=\"source\">PDF p. 2103</small><p>Methadone PO: 0.05–0.1 mg/kg/dose every 6–24 h</p><small class=\"source\">PDF p. 2103</small><p>Comments</p><small class=\"source\">PDF p. 2103</small><p>Must have continuous intra-arterial blood</p><small class=\"source\">PDF p. 2103</small><p>pressure monitoring; may produce profound hypotension, metabolic acidosis, thrombocytopenia, and/or CNS symptoms; cyanide toxicity can occur.</p><small class=\"source\">PDF p. 2103</small><p>Typical starting dose is 5–10 μg/kg/</p><small class=\"source\">PDF p. 2103</small><p>min, then titrate to effect; increases myocardial contractility and cardiac output; tachycardia may occur.</p><small class=\"source\">PDF p. 2103</small><p>Typical starting dose is 5–10 μg/kg/</p><small class=\"source\">PDF p. 2103</small><p>min, then titrate to effect; increases myocardial contractility and cardiac output and causes vasoconstriction; predominant effects vary with dose; tachycardia may occur.</p><small class=\"source\">PDF p. 2103</small><p>Increases blood pressure via direct</p><small class=\"source\">PDF p. 2103</small><p>myocardial stimulation, increased heart rate, and vasoconstriction; monitor for hyperglycemia and tachycardia.</p><small class=\"source\">PDF p. 2103</small><p>Primarily acts by increasing heart rate;</p><small class=\"source\">PDF p. 2103</small><p>monitor for tachycardia.</p><small class=\"source\">PDF p. 2103</small><p>Has both inotropic and vasodilatory</p><small class=\"source\">PDF p. 2103</small><p>properties; hypotension occurs frequently with loading dose, so avoid if possible.</p><small class=\"source\">PDF p. 2103</small><p>Hepatotoxicity occurs in less than 0.01%</p><small class=\"source\">PDF p. 2103</small><p>of children receiving therapeutic doses.</p><small class=\"source\">PDF p. 2103</small><p>Apnea occurs in 10%–12% of neonates.</p><small class=\"source\">PDF p. 2103</small><p>Monitor urine output; can inhibit platelet</p><small class=\"source\">PDF p. 2103</small><p>aggregation; avoid concomitant steroid therapy to decrease risk of GI perforation.</p><small class=\"source\">PDF p. 2103</small><p>Monitor urine output; can cause platelet</p><small class=\"source\">PDF p. 2103</small><p>dysfunction; avoid concomitant steroid therapy to decrease risk of GI perforation.</p><small class=\"source\">PDF p. 2103</small><p>Dosing interval is dependent on</p><small class=\"source\">PDF p. 2103</small><p>postmenstrual age; round up to the nearest 1⁄2 suppository increment for rectal administration.</p><small class=\"source\">PDF p. 2103</small><p>Synthetic opioid; may cause chest wall</p><small class=\"source\">PDF p. 2103</small><p>rigidity with higher doses or with rapid infusion.</p><small class=\"source\">PDF p. 2103</small><p>For treatment of neonatal opioid</p><small class=\"source\">PDF p. 2103</small><p>withdrawal syndrome, adjust dose in 10%–20% increments based on signs and symptoms of withdrawal. Use of an institution-specific guideline is recommended.</p><small class=\"source\">PDF p. 2103</small><figure class=\"source-page\"><a href=\"tables/ch104_page2103.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch104_page2103.jpg\" alt=\"Original source page 2103, including its figures or tables\"></a><figcaption>Original source-page view · PDF 2103. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"2104\"><h2>PDF page 2104 · Printed 2114</h2><h3>Overview</h3><p>Agent Dosage</p><small class=\"source\">PDF p. 2104</small><p>Morphine IV, IM, subcutaneous: 0.05–0.2 mg/kg/dose every 4 h Continuous IV infusion: 10–20 μg/kg/h; increase based on</p><small class=\"source\">PDF p. 2104</small><p>response Neonatal abstinence syndrome: 0.03–0.1 mg/kg/dose</p><small class=\"source\">PDF p. 2104</small><p>PO: every 3–4 h; adjust dose based on abstinence scoring</p><small class=\"source\">PDF p. 2104</small><p>Anticonvulsants</p><small class=\"source\">PDF p. 2104</small><p>Fosphenytoin Loading dose: 15–20 mg PE/kg IV, IM Maintenance dose: 2–4 mg PE/kg IV, IM every 12 h</p><small class=\"source\">PDF p. 2104</small><p>Levetiracetam 10 mg/kg/dose IV, PO every 12 h; increase dose as</p><small class=\"source\">PDF p. 2104</small><p>needed up to maximum of 30 mg/kg/dose every 12 h</p><small class=\"source\">PDF p. 2104</small><p>Lidocaine Loading dose: 2 mg/kg IV over 10 min Maintenance infusion: 6 mg/kg/h for 6 h, then 4 mg/kg/h</p><small class=\"source\">PDF p. 2104</small><p>for 12 h, then 2 mg/kg/h for 12 h</p><small class=\"source\">PDF p. 2104</small><p>Phenobarbital Loading dose: 20 mg/kg slow IV push; additional 10 mg/</p><small class=\"source\">PDF p. 2104</small><p>kg doses may be given up to a total of 40 mg/kg Maintenance dose: 3–5 mg/kg/dose IV, IM, PO every 24 h</p><small class=\"source\">PDF p. 2104</small><p>Phenytoin Loading dose: 15–20 mg/kg IV over 30 min Maintenance dose: 4–8 mg/kg/dose IV, PO every 8–24 h</p><small class=\"source\">PDF p. 2104</small><p>Neuromuscular Blockersb</p><small class=\"source\">PDF p. 2104</small><p>Pancuronium 0.1 mg/kg IV push every 1–2 h as needed</p><small class=\"source\">PDF p. 2104</small><p>Rocuronium 0.6–1.2 mg/kg IV push; repeat as needed (every</p><small class=\"source\">PDF p. 2104</small><p>30–60 min)</p><small class=\"source\">PDF p. 2104</small><p>Vecuronium 0.1 mg/kg IV push, every 1–2 h as needed Continuous IV infusion: 0.06–0.2 mg/kg/h</p><small class=\"source\">PDF p. 2104</small><p>Sedatives/Tranquilizers</p><small class=\"source\">PDF p. 2104</small><p>Clonidine 0.5–1 μg/kg/dose PO every 4–6 h</p><small class=\"source\">PDF p. 2104</small><p>Lorazepam 0.05–0.1 mg/kg/dose IV push</p><small class=\"source\">PDF p. 2104</small><p>Midazolam IV, IM: 0.05–0.15 mg/kg/dose every 2–4 h Continuous IV infusion: 10–20 μg/kg/h; increase as</p><small class=\"source\">PDF p. 2104</small><p>needed Intranasal: 0.2–0.3 mg/kg/dose prior to procedure (use 5</p><small class=\"source\">PDF p. 2104</small><p>mg/mL injectable form) Oral: 0.25 mg/kg/dose every 4–6 h</p><small class=\"source\">PDF p. 2104</small><p>Diuretics</p><small class=\"source\">PDF p. 2104</small><p>Bumetanidea 0.005–0.1 mg/kg/dose IV, IM, PO every 12–24 h</p><small class=\"source\">PDF p. 2104</small><p>Chlorothiazide PO: 10–20 mg/kg/dose every 12 h IV: 5–10 mg/kg/dose every 12 h</p><small class=\"source\">PDF p. 2104</small><p>Comments</p><small class=\"source\">PDF p. 2104</small><p>May exacerbate hypotension and</p><small class=\"source\">PDF p. 2104</small><p>cause respiratory depression. Use of an institution-specific guideline is recommended when treating neonatal opioid withdrawal syndrome.</p><small class=\"source\">PDF p. 2104</small><p>Fosphenytoin 1 mg PE = phenytoin</p><small class=\"source\">PDF p. 2104</small><p>1 mg; IV route preferred over IM when possible. Monitor trough serum phenytoin concentrations, and use with caution in neonates with hyperbilirubinemia.</p><small class=\"source\">PDF p. 2104</small><p>Treatment of seizures refractory to</p><small class=\"source\">PDF p. 2104</small><p>phenobarbital and other anticonvulsants.</p><small class=\"source\">PDF p. 2104</small><p>Preterm newborns and newborns</p><small class=\"source\">PDF p. 2104</small><p>undergoing hypothermia treatment are at risk for drug accumulation; precise dosing in these infants is uncertain.</p><small class=\"source\">PDF p. 2104</small><p>Monitor serum concentrations, and adjust</p><small class=\"source\">PDF p. 2104</small><p>dose to maintain concentrations at 15–40 μg/mL.</p><small class=\"source\">PDF p. 2104</small><p>Infants &gt;1 wk of age may require more</p><small class=\"source\">PDF p. 2104</small><p>frequent dosing.</p><small class=\"source\">PDF p. 2104</small><p>Tachycardia, hypotension, and</p><small class=\"source\">PDF p. 2104</small><p>hypertension occur frequently.</p><small class=\"source\">PDF p. 2104</small><p>Short duration of action; use limited to</p><small class=\"source\">PDF p. 2104</small><p>premedication for procedures such as intubation.</p><small class=\"source\">PDF p. 2104</small><p>Minimal cardiovascular side effects.</p><small class=\"source\">PDF p. 2104</small><p>Adjunct treatment of neonatal opioid</p><small class=\"source\">PDF p. 2104</small><p>withdrawal syndrome; limited data available.</p><small class=\"source\">PDF p. 2104</small><p>May cause respiratory depression; may</p><small class=\"source\">PDF p. 2104</small><p>be used acutely to stop seizures. Some products contain benzyl alcohol.</p><small class=\"source\">PDF p. 2104</small><p>Dosage requirements are decreased by</p><small class=\"source\">PDF p. 2104</small><p>concurrent use of narcotics. Monitor for respiratory depression and hypotension; may cause myoclonic seizure-like activity.</p><small class=\"source\">PDF p. 2104</small><p>May cause hyponatremia, hypokalemia,</p><small class=\"source\">PDF p. 2104</small><p>and hypochloremic alkalosis; may displace bilirubin from albumin-binding sites when given in high doses or for prolonged periods.</p><small class=\"source\">PDF p. 2104</small><p>May cause hypokalemia and</p><small class=\"source\">PDF p. 2104</small><p>alkalosis; effective in treatment of nephrocalcinosis secondary to loop diuretics.</p><small class=\"source\">PDF p. 2104</small><figure class=\"source-page\"><a href=\"tables/ch104_page2104.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch104_page2104.jpg\" alt=\"Original source page 2104, including its figures or tables\"></a><figcaption>Original source-page view · PDF 2104. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"2105\"><h2>PDF page 2105 · Printed 2115</h2><h3>Overview</h3><p>Agent Dosage</p><small class=\"source\">PDF p. 2105</small><p>Furosemidea IV: 1–2 mg/kg/dose every 6–24 h PO: 2–6 mg/kg/dose every 6–24 h</p><small class=\"source\">PDF p. 2105</small><p>Hydrochlorothiazide 1–2 mg/kg/dose PO every 12 h</p><small class=\"source\">PDF p. 2105</small><p>Spironolactone 1–3 mg/kg/dose PO every 24 h</p><small class=\"source\">PDF p. 2105</small><p>Endocrine Agents</p><small class=\"source\">PDF p. 2105</small><p>Dexamethasone DART (Dexamethasone: A Randomized Trial) protocol:</p><small class=\"source\">PDF p. 2105</small><p>0.075 mg/kg/dose IV, PO every 12 h for 3 d, then wean over 7 d (10-d course) Airway extubation: 0.25 mg/kg/dose IV, PO every 8 h for</p><small class=\"source\">PDF p. 2105</small><p>3 doses</p><small class=\"source\">PDF p. 2105</small><p>Diazoxide 2–5 mg/kg/dose PO every 8 h</p><small class=\"source\">PDF p. 2105</small><p>Glucagon 0.2 mg/kg/dose IV, IM, or subcutaneous (maximum dose</p><small class=\"source\">PDF p. 2105</small><p>1 mg)</p><small class=\"source\">PDF p. 2105</small><p>Hydrocortisone Physiologic dose: 7–9 mg/m2/d IV, PO divided every12 h Stress dose: 20–40 mg/m2/d IV divided every 6–12 h</p><small class=\"source\">PDF p. 2105</small><p>Insulin Hyperglycemia: continuous IV infusion 0.01–0.1 units/kg/h Hyperkalemia: continuous IV infusion 0.1–0.2 units/kg/h</p><small class=\"source\">PDF p. 2105</small><p>with 0.5 g/kg/h of continuous dextrose (equivalent to D10W at 120 mL/kg/d)</p><small class=\"source\">PDF p. 2105</small><p>Levothyroxine PO: 10–15 μg/kg/dose every 24 h IV: 5–8 μg/kg/dose every 24 h</p><small class=\"source\">PDF p. 2105</small><p>Octreotide Hyperinsulinemic hypoglycemia: 1 μg/kg/dose IV,</p><small class=\"source\">PDF p. 2105</small><p>subcutaneous every 6 h; titrate to desired effect; maximum dose is 10 μg/kg/dose every 6 h Chylothorax: 1 μg/kg/h, titrate up by 1 μg/kg/h every 24</p><small class=\"source\">PDF p. 2105</small><p>h; maximum dose is 10 μg/kg/h</p><small class=\"source\">PDF p. 2105</small><p>Gastrointestinal Agents</p><small class=\"source\">PDF p. 2105</small><p>Erythromycin 10 mg/kg/dose PO every 6 h for 2 d, then 4 mg/kg/dose</p><small class=\"source\">PDF p. 2105</small><p>every 6 h for 5 d</p><small class=\"source\">PDF p. 2105</small><p>Famotidine IV: 0.25–0.5 mg/kg/dose every 24 h PO: 0.5–1 mg/kg/dose every 24 h</p><small class=\"source\">PDF p. 2105</small><p>Lansoprazole 1 mg/kg/dose PO every 24 h</p><small class=\"source\">PDF p. 2105</small><p>Metoclopramide 0.03–0.1 mg/kg/dose IV, PO every 8 h</p><small class=\"source\">PDF p. 2105</small><p>Omeprazole 1 mg/kg/dose PO every 24 h</p><small class=\"source\">PDF p. 2105</small><p>Comments</p><small class=\"source\">PDF p. 2105</small><p>Potentially ototoxic and may cause</p><small class=\"source\">PDF p. 2105</small><p>hypokalemia, hyponatremia, alkalosis, and nephrocalcinosis; consider alternate-day therapy for long-term use.</p><small class=\"source\">PDF p. 2105</small><p>May cause hypokalemia.</p><small class=\"source\">PDF p. 2105</small><p>Use in combination with other diuretics;</p><small class=\"source\">PDF p. 2105</small><p>may cause hyperkalemia.</p><small class=\"source\">PDF p. 2105</small><p>Treat only those infants at highest risk of</p><small class=\"source\">PDF p. 2105</small><p>chronic lung disease; adverse effects include growth failure, hypertension, hyperglycemia, and increased risk for cerebral palsy. There is an increased risk of GI perforation when treating concurrently with indomethacin/ ibuprofen.</p><small class=\"source\">PDF p. 2105</small><p>Reserved for treatment of severe,</p><small class=\"source\">PDF p. 2105</small><p>persistent hypoglycemia caused by hyperinsulinism; often causes sodium and fluid retention and may cause GI distention.</p><small class=\"source\">PDF p. 2105</small><p>Reserved for treatment of refractory</p><small class=\"source\">PDF p. 2105</small><p>hypoglycemia; watch for rebound hypoglycemia approximately 2 h after dose.</p><small class=\"source\">PDF p. 2105</small><p>Adverse effects include hyperglycemia,</p><small class=\"source\">PDF p. 2105</small><p>hypertension, and water and salt retention; there is an increased risk of GI perforation when treating concurrently with indomethacin/ibuprofen.</p><small class=\"source\">PDF p. 2105</small><p>Binds to plastic tubing; to saturate tubing</p><small class=\"source\">PDF p. 2105</small><p>binding sites, fill tubing with insulin solution and wait at least 20 min prior to administration.</p><small class=\"source\">PDF p. 2105</small><p>Adjust oral doses in 12.5 μg increments,</p><small class=\"source\">PDF p. 2105</small><p>always round up; assess thyroid function 2 weeks after dosing change.</p><small class=\"source\">PDF p. 2105</small><p>May cause vomiting, diarrhea, abdominal</p><small class=\"source\">PDF p. 2105</small><p>distention; NEC has been reported in term neonates.</p><small class=\"source\">PDF p. 2105</small><p>Treatment of feeding intolerance caused</p><small class=\"source\">PDF p. 2105</small><p>by GI dysmotility; pyloric stenosis has been reported with use.</p><small class=\"source\">PDF p. 2105</small><p>May increase risk for late-onset sepsis,</p><small class=\"source\">PDF p. 2105</small><p>necrotizing enterocolitis, pneumonia, upper respiratory tract infections.</p><small class=\"source\">PDF p. 2105</small><p>Limited data are available in neonates.</p><small class=\"source\">PDF p. 2105</small><p>Facilitates gastric emptying and</p><small class=\"source\">PDF p. 2105</small><p>gastrointestinal motility; observe for dystonic reactions.</p><small class=\"source\">PDF p. 2105</small><p>May increase risk for late-onset sepsis,</p><small class=\"source\">PDF p. 2105</small><p>necrotizing enterocolitis, pneumonia, and upper respiratory tract infections.</p><small class=\"source\">PDF p. 2105</small><figure class=\"source-page\"><a href=\"tables/ch104_page2105.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch104_page2105.jpg\" alt=\"Original source page 2105, including its figures or tables\"></a><figcaption>Original source-page view · PDF 2105. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"2106\"><h2>PDF page 2106 · Printed 2116</h2><h3>Overview</h3><p>Agent Dosage</p><small class=\"source\">PDF p. 2106</small><p>Ranitidine PO: 2 mg/kg/dose every 8 h IV preterm: 0.5 mg/kg/dose every 12 h IV term: 1.5 mg/kg/dose every 8 h Continuous IV infusion: 0.0625 mg/kg/h</p><small class=\"source\">PDF p. 2106</small><p>Ursodiol 10–15 mg/kg/dose PO every 12 h</p><small class=\"source\">PDF p. 2106</small><p>Hematologic Agents</p><small class=\"source\">PDF p. 2106</small><p>Alteplase (t-PA) Dissolution of intravascular thrombi: 200 μg/kg/h for 6–48 h Restoration of patency for central venous catheter: instill a</p><small class=\"source\">PDF p. 2106</small><p>1-mg/mL solution into the catheter and dwell up to 120 min; may repeat once if needed</p><small class=\"source\">PDF p. 2106</small><p>Enoxaparin Term: 1.7 mg/kg/dose subcutaneous every 12 h Preterm: 2 mg/kg/dose subcutaneous every 12 h</p><small class=\"source\">PDF p. 2106</small><p>Epoetin alfa 200–400 units/kg/dose subcutaneous 3–5 times/wk for</p><small class=\"source\">PDF p. 2106</small><p>2–6 weeks</p><small class=\"source\">PDF p. 2106</small><p>Heparin Thrombosis: 75 units/kg IV, then 28 units/kg/h Maintenance of central line patency: 0.5–1 unit/mL of IV</p><small class=\"source\">PDF p. 2106</small><p>fluid</p><small class=\"source\">PDF p. 2106</small><p>IVIG 400–1000 mg/kg/dose IV over 2–6 h</p><small class=\"source\">PDF p. 2106</small><p>Minerals/Vitamins</p><small class=\"source\">PDF p. 2106</small><p>Calcium carbonate 20–80 mg/kg/d elemental calcium PO every 6–12 h</p><small class=\"source\">PDF p. 2106</small><p>Calcium gluconate</p><small class=\"source\">PDF p. 2106</small><p>Acute treatment: 100–200 mg/kg/dose IV (equivalent to</p><small class=\"source\">PDF p. 2106</small><p>10%</p><small class=\"source\">PDF p. 2106</small><p>10–20 mg/kg elemental calcium) Maintenance treatment: 200–800 mg/kg/d by continuous</p><small class=\"source\">PDF p. 2106</small><p>IV infusion (20–80 mg/kg elemental calcium)</p><small class=\"source\">PDF p. 2106</small><p>Ferrous sulfate 2–6 mg/kg/d elemental iron divided every 12–24 h</p><small class=\"source\">PDF p. 2106</small><p>Iron dextran 0.4–1 mg/kg/d continuous IV infusion in parenteral</p><small class=\"source\">PDF p. 2106</small><p>nutrition solution</p><small class=\"source\">PDF p. 2106</small><p>Potassium chloride Acute treatment of symptomatic hypokalemia: begin with</p><small class=\"source\">PDF p. 2106</small><p>0.5–1 mEq/kg IV over 1 h, then reassess Initial oral replacement: 1–2 mEq/kg/d PO divided and</p><small class=\"source\">PDF p. 2106</small><p>administered with feedings</p><small class=\"source\">PDF p. 2106</small><p>Pyridoxine (vitamin B6) Initial diagnostic dose: 50–100 mg IV, IM Maintenance dose: 50–100 mg PO every 24 h</p><small class=\"source\">PDF p. 2106</small><p>Sodium bicarbonate 1–2 mEq/kg/dose IV over at least 30 min</p><small class=\"source\">PDF p. 2106</small><p>Vitamin D Supplementation: 200–400 units PO every 24 h Treatment of deficiency: 1000 units/d divided every 12–24 h</p><small class=\"source\">PDF p. 2106</small><p>Vitamin K1 Prophylaxis: ≤1500 g: 0.5 mg IM at birth &gt;1500 g: 1 mg IM at birth Treatment of VKDB: 1–10 mg IV, IM, or Subq</p><small class=\"source\">PDF p. 2106</small><p>Ophthalmic Agents</p><small class=\"source\">PDF p. 2106</small><p>Cyclopentolate 1–2 drops in the eye 10–30 min before funduscopy</p><small class=\"source\">PDF p. 2106</small><p>Comments</p><small class=\"source\">PDF p. 2106</small><p>May increase risk for late-onset sepsis,</p><small class=\"source\">PDF p. 2106</small><p>necrotizing enterocolitis, pneumonia, and upper respiratory tract infections.</p><small class=\"source\">PDF p. 2106</small><p>May cause vomiting, abdominal pain, and</p><small class=\"source\">PDF p. 2106</small><p>constipation.</p><small class=\"source\">PDF p. 2106</small><p>Thrombi dose is a range of that used in</p><small class=\"source\">PDF p. 2106</small><p>case reports (20–500 μg/kg/h); call 1-800-NOCLOTS for case reporting and treatment guidance.</p><small class=\"source\">PDF p. 2106</small><p>Adjust dose to maintain antifactor Xa level</p><small class=\"source\">PDF p. 2106</small><p>between 0.5 and 1 unit/mL.</p><small class=\"source\">PDF p. 2106</small><p>Patient should be on supplemental iron</p><small class=\"source\">PDF p. 2106</small><p>therapy.</p><small class=\"source\">PDF p. 2106</small><p>For thrombosis, adjust dose based on</p><small class=\"source\">PDF p. 2106</small><p>aPTT or anti-factor Xa level.</p><small class=\"source\">PDF p. 2106</small><p>If more than one dose is needed, may</p><small class=\"source\">PDF p. 2106</small><p>repeat in 12–24 h.</p><small class=\"source\">PDF p. 2106</small><p>—</p><small class=\"source\">PDF p. 2106</small><p>Monitor serum calcium and ionized</p><small class=\"source\">PDF p. 2106</small><p>calcium if possible.</p><small class=\"source\">PDF p. 2106</small><p>Use 6 mg/kg/d for infants on epoetin</p><small class=\"source\">PDF p. 2106</small><p>therapy.</p><small class=\"source\">PDF p. 2106</small><p>For infants unable to tolerate oral iron</p><small class=\"source\">PDF p. 2106</small><p>therapy.</p><small class=\"source\">PDF p. 2106</small><p>Typical maximum concentrations are</p><small class=\"source\">PDF p. 2106</small><p>40 mEq/L for peripheral and 120 mEq/L for central venous infusions.</p><small class=\"source\">PDF p. 2106</small><p>May cause bradycardia, apnea,</p><small class=\"source\">PDF p. 2106</small><p>hypotension.</p><small class=\"source\">PDF p. 2106</small><p>Maximum concentration 0.5 mEq/</p><small class=\"source\">PDF p. 2106</small><p>mL; treatment of normal anion gap metabolic acidosis caused by renal or GI losses; not a recommended therapy in neonatal resuscitation.</p><small class=\"source\">PDF p. 2106</small><p>Vitamin D3 (cholecalciferol) has been</p><small class=\"source\">PDF p. 2106</small><p>shown to be more effective in raising 25(OH)-D levels when compared with vitamin D2 (ergocalciferol).</p><small class=\"source\">PDF p. 2106</small><p>For treatment of VKDB, the Subq and</p><small class=\"source\">PDF p. 2106</small><p>IV route are preferred; avoid IM in the presence of coagulopathy.</p><small class=\"source\">PDF p. 2106</small><p>Use solutions with concentrations of 0.5%</p><small class=\"source\">PDF p. 2106</small><p>or less in neonates; anticholinergic effects occur if absorbed systemically. Apply pressure to lacrimal sac during and for 2 min after instillation.</p><small class=\"source\">PDF p. 2106</small><figure class=\"source-page\"><a href=\"tables/ch104_page2106.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch104_page2106.jpg\" alt=\"Original source page 2106, including its figures or tables\"></a><figcaption>Original source-page view · PDF 2106. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section><section class=\"source-section\" data-pdf-page=\"2107\"><h2>PDF page 2107 · Printed 2117</h2><h3>Overview</h3><p>Agent Dosage</p><small class=\"source\">PDF p. 2107</small><p>Phenylephrine 1 drop in eye 10–30 min before funduscopy</p><small class=\"source\">PDF p. 2107</small><p>Tropicamide 1 drop in eye 10–30 min before funduscopy</p><small class=\"source\">PDF p. 2107</small><p>Pulmonary Agents</p><small class=\"source\">PDF p. 2107</small><p>Albuterol Nebulizer: 2.5 mg/3 mL every 2–6 hours MDI: 2 puffs every 2–6 h</p><small class=\"source\">PDF p. 2107</small><p>Aminophylline Loading dose: 8 mg/kg IV Maintenance dose: 1.5–3 mg/kg/dose IV, PO every 8–12 h</p><small class=\"source\">PDF p. 2107</small><p>Beractant (Survanta) 4 mL/kg/dose intratracheally; may repeat every 6 h up to a</p><small class=\"source\">PDF p. 2107</small><p>total of 4 doses</p><small class=\"source\">PDF p. 2107</small><p>Caffeine citrate Loading dose: 20 mg/kg IV, PO Maintenance dose: 5–10 mg/kg/dose IV, PO every 24 h</p><small class=\"source\">PDF p. 2107</small><p>Calfactant (Infasurf) 3 mL/kg/dose intratracheally; may repeat every 12 h up to</p><small class=\"source\">PDF p. 2107</small><p>a total of 3 doses</p><small class=\"source\">PDF p. 2107</small><p>Dornase alpha 1.25–2.5 mL via nebulizer or 0.2 mL/kg instilled directly</p><small class=\"source\">PDF p. 2107</small><p>into endotracheal tube every 12–24 h</p><small class=\"source\">PDF p. 2107</small><p>Ipratropium bromide MDI: 2–4 puffs every 6–8 h Nebulizer: 125–250 μg/dose every 6–8 h</p><small class=\"source\">PDF p. 2107</small><p>Poractant alfa</p><small class=\"source\">PDF p. 2107</small><p>2.5 mL/kg/dose intratracheally; may repeat dose of</p><small class=\"source\">PDF p. 2107</small><p>(Curosurf)</p><small class=\"source\">PDF p. 2107</small><p>1.25 mL/kg every 12 h up to a total of 3 doses</p><small class=\"source\">PDF p. 2107</small><p>Theophylline 0.7–3 mg/kg/dose every 8–12 h</p><small class=\"source\">PDF p. 2107</small><p>Reversal Agents/Antidotes</p><small class=\"source\">PDF p. 2107</small><p>Flumazenil IV: 5–10 μg/kg/dose; repeat every 45 s up to maximum</p><small class=\"source\">PDF p. 2107</small><p>cumulative dose of 50 μg/kg or 1 mg (whichever is smaller) Intranasal: 40 μg/kg/dose divided between each nostril Rectal: 15–30 μg/kg/dose; repeat after 15–20 min if</p><small class=\"source\">PDF p. 2107</small><p>needed</p><small class=\"source\">PDF p. 2107</small><p>Hyaluronidase 150 units subcutaneous as 5 separate injections around</p><small class=\"source\">PDF p. 2107</small><p>the site of extravasation</p><small class=\"source\">PDF p. 2107</small><p>Naloxone 0.1 mg/kg/dose IV every 2–3 min; may need to repeat</p><small class=\"source\">PDF p. 2107</small><p>doses in 20–60 min</p><small class=\"source\">PDF p. 2107</small><p>Phentolamine Inject 1–5 mL of a 0.5 mg/mL solution subcutaneous into</p><small class=\"source\">PDF p. 2107</small><p>the periphery of the affected area</p><small class=\"source\">PDF p. 2107</small><p>Protamine 0.25–1 mg per 100 units heparin received IV; maximum</p><small class=\"source\">PDF p. 2107</small><p>dose 50 mg</p><small class=\"source\">PDF p. 2107</small><p>Comments</p><small class=\"source\">PDF p. 2107</small><p>Use only the 2.5% solution in neonates;</p><small class=\"source\">PDF p. 2107</small><p>apply pressure to lacrimal sac during and for 2 min after instillation.</p><small class=\"source\">PDF p. 2107</small><p>Use only the 0.5% solution in neonates;</p><small class=\"source\">PDF p. 2107</small><p>anticholinergic effects occur if absorbed systemically. Apply pressure to lacrimal sac during and for 2 min after instillation.</p><small class=\"source\">PDF p. 2107</small><p>Selective β2-agonist.</p><small class=\"source\">PDF p. 2107</small><p>Follow serum trough concentrations:</p><small class=\"source\">PDF p. 2107</small><p>target 7–12 μg/L.</p><small class=\"source\">PDF p. 2107</small><p>—</p><small class=\"source\">PDF p. 2107</small><p>Monitoring serum levels is not necessary if</p><small class=\"source\">PDF p. 2107</small><p>using recommended doses.</p><small class=\"source\">PDF p. 2107</small><p>—</p><small class=\"source\">PDF p. 2107</small><p>Desaturation and/or airway obstruction</p><small class=\"source\">PDF p. 2107</small><p>may occur due to rapid mobilization of secretions.</p><small class=\"source\">PDF p. 2107</small><p>Precise dosing is uncertain, although the</p><small class=\"source\">PDF p. 2107</small><p>therapeutic margin is wide.</p><small class=\"source\">PDF p. 2107</small><p>—</p><small class=\"source\">PDF p. 2107</small><p>IV aminophylline dose is equivalent to PO</p><small class=\"source\">PDF p. 2107</small><p>theophylline dose; follow serum trough concentrations: target 7–12 μg/L.</p><small class=\"source\">PDF p. 2107</small><p>Reversal of sedative effect from</p><small class=\"source\">PDF p. 2107</small><p>benzodiazepines.</p><small class=\"source\">PDF p. 2107</small><p>Initiate treatment as soon as possible after</p><small class=\"source\">PDF p. 2107</small><p>extravasation.</p><small class=\"source\">PDF p. 2107</small><p>Reversal of narcotic-induced respiratory/</p><small class=\"source\">PDF p. 2107</small><p>CNS depression; not recommended as part of delivery room resuscitation.</p><small class=\"source\">PDF p. 2107</small><p>Prevention of dermal necrosis caused</p><small class=\"source\">PDF p. 2107</small><p>by extravasation of vasoconstrictive agents.</p><small class=\"source\">PDF p. 2107</small><p>Heparin antagonist; exact dose depends</p><small class=\"source\">PDF p. 2107</small><p>on time in min since last heparin dose; may cause hypotension, bradycardia, dyspnea, or transitory flushing.</p><small class=\"source\">PDF p. 2107</small><figure class=\"source-page\"><a href=\"tables/ch104_page2107.jpg\" target=\"_blank\"><img loading=\"lazy\" src=\"tables/ch104_page2107.jpg\" alt=\"Original source page 2107, including its figures or tables\"></a><figcaption>Original source-page view · PDF 2107. Use this view to check table relationships, figures, footnotes and source credits.</figcaption></figure></section>", "guided": {"num": 104, "title": "Therapeutic Agents", "hook": "Read drug tables as contextual references: formulation, units, indication, monitoring and developmental age must travel with the dose.", "audience": "Pediatric residents, neonatal fellows and clinicians studying the source edition", "prerequisites": "Core neonatal physiology and clinical assessment; foundational chapters support entry-level review.", "estimated_minutes": 25, "estimated_minutes_note": "Planning estimate for five units and feedback; full reference reading takes longer.", "lessons": [{"id": "L104-1", "objective_id": "O104-1", "objective": "Identify the age variables required for marked table entries", "title": "Developmental dosing", "level": "Clinical Application", "text": "Postmenstrual and postnatal age. The footnote specifies dependence on postmenstrual and postnatal age; a printed range is not a complete individualized prescription.", "card_id": "fc-104-1", "question_id": "q-104-1", "pdf_page": 2107, "printed_page": "2117"}, {"id": "L104-2", "objective_id": "O104-2", "objective": "Identify a ceftriaxone caution from the source table", "title": "Compatibility and bilirubin", "level": "Clinical Application", "text": "Avoid its use in hyperbilirubinemia and do not administer in the same IV line with calcium-containing solutions. The source row includes both bilirubin and same-line calcium cautions; these are essential parts of reading the entry.", "card_id": "fc-104-2", "question_id": "q-104-2", "pdf_page": 2099, "printed_page": "2109"}, {"id": "L104-3", "objective_id": "O104-3", "objective": "Interpret phenytoin-equivalent notation", "title": "Equivalent units", "level": "Clinical Application", "text": "Phenytoin-equivalent amount rather than an unspecified mass of product. The table defines PE as phenytoin equivalent and relates one mg PE to one mg phenytoin; product units must remain explicit.", "card_id": "fc-104-3", "question_id": "q-104-3", "pdf_page": 2104, "printed_page": "2114"}, {"id": "L104-4", "objective_id": "O104-4", "objective": "Recognize what neuromuscular blockade does not provide", "title": "Paralysis and comfort", "level": "Clinical Application", "text": "Blockade provides neither analgesia nor amnesia, so effective sedation/analgesia must accompany it. The footnote states that these agents provide neither analgesia nor amnesia, so visible immobility cannot establish comfort.", "card_id": "fc-104-4", "question_id": "q-104-4", "pdf_page": 2107, "printed_page": "2117"}, {"id": "L104-5", "objective_id": "O104-5", "objective": "Select the monitoring assay specified for enoxaparin", "title": "Anticoagulant monitoring", "level": "Clinical Application", "text": "Anti-factor Xa activity. The enoxaparin row specifies anti-factor Xa-guided adjustment; bleeding assessment and other monitoring remain clinically relevant.", "card_id": "fc-104-5", "question_id": "q-104-5", "pdf_page": 2106, "printed_page": "2116"}], "unavailable_levels": ["Essentials", "Deep Dive"], "review_status": "Model checked selected cited source passages; not specialist review", "case": null}});
